CREATE OR REPLACE FUNCTION create_default_metric_record()
RETURNS TRIGGER AS $ 
BEGIN 
    INSERT INTO interactionmetrics (intmetkey, interaction_behavior) 
    VALUES (NEW.intkey, '{}'); 
    RETURN NEW; 
END; 
$ LANGUAGE plpgsql;

CREATE TRIGGER create_metric_record_trigger
AFTER INSERT ON interactions
FOR EACH ROW EXECUTE FUNCTION create_default_metric_record();

